function employeeRows(){return data.employees.filter(e=>(required(e,date,'midday',data.leaves,data.holidays)||required(e,date,'eod',data.leaves,data.holidays)||e.active)&&(!search||(e.full_name+' '+e.email).toLowerCase().includes(search.toLowerCase()))&&(team==='all'||e.department===team)).map(e=>{let a=status(e,date,'midday',data,now()),b=status(e,date,'eod',data,now());return {e,a,b,o:overall(a,b)}}).filter(r=>filter==='all'||r.o===filter)}
function overview(){const rows=employeeRows(),all=data.employees.filter(e=>e.active).map(e=>{const a=status(e,date,'midday',data,now()),b=status(e,date,'eod',data,now());return {e,a,b,o:overall(a,b)}}),req=all.filter(r=>r.o!=='Exempt');shell(heading('Flexible starts. Shared accountability.','Eight working hours. Two meaningful updates. One clear view.',`<div class="row"><input aria-label="Tracking date" type="date" id="date" value="${date}"><button class="btn" id="export">↓ Export CSV</button></div>`)+`<div class="stats">${[[req.length,'Employees required','Based on roster and available exemptions'],[req.filter(r=>r.o==='Complete'||r.o==='Complete · Exception').length,'Updates complete','Exceptions remain separately visible'],[all.filter(r=>r.o==='Review needed'||staleSession(data.sessions.find(w=>w.employee_id===r.e.id&&w.work_date===date),now())).length,'Needs review','Mid-day reasons or session corrections'],[all.filter(r=>r.o==='No Update').length,'No updates','Check session and leave context first']].map(([n,l,t])=>`<div class="stat"><div class="label">${l}</div><div class="num">${n}</div><small>${t}</small></div>`).join('')}</div><div class="notice">Leave stays in the existing HR portal. Automatic leave exclusion is not connected. Today’s results are provisional.</div><section class="panel"><div class="panel-head"><div><h2>Daily compliance</h2><p>Mid-day due at 4 net hours · EOD before sign-out · 8h work target · Breaks excluded</p></div>${badge('Flexible sign-in')}</div><div class="toolbar"><input type="search" id="search" placeholder="Search employee name or email…" value="${esc(search)}" aria-label="Search employees"><select id="team" aria-label="Department"><option value="all">All departments</option>${[...new Set(data.employees.map(e=>e.department))].map(t=>`<option ${team===t?'selected':''}>${esc(t)}</option>`).join('')}</select><select id="filter" aria-label="Compliance status">${['all','Complete','Complete · Exception','Partial','Review needed','In progress','No Update','Exempt'].map(v=>`<option value="${v}" ${filter===v?'selected':''}>${v==='all'?'All statuses':v}</option>`).join('')}</select></div><table class="data-table"><thead><tr><th>Employee</th><th>Work session</th><th>Mid-day</th><th>EOD</th><th>Overall</th><th></th></tr></thead><tbody>${rows.map(r=>{const w=data.sessions.find(x=>x.employee_id===r.e.id&&x.work_date===date);return `<tr><td>${person(r.e)}</td><td data-label="Work session">${w?`<div>${duration(sessionSeconds(w,now()))}<br>${badge(hoursLabel(w,now()))}</div>`:badge('Not signed in')}</td><td data-label="Mid-day">${badge(r.a)}</td><td data-label="EOD">${badge(r.b)}</td><td data-label="Overall">${badge(r.o)}</td><td><button class="text-button" data-view="${r.e.id}">View →</button></td></tr>`}).join('')||'<tr><td colspan="6" class="empty">No employee data yet. Add your roster when ready.</td></tr>'}</tbody></table><div class="table-foot">All ${rows.length} matching employees · Session hours and update compliance are separate.</div></section><div class="note">No fixed clock-in time or late-start penalty. Hours are based on recorded sessions, not proof of productivity. A Mid-day reason remains pending until HR reviews it.</div>`)}
function updates(){if(!connected&&!previewEmployee&&data.employees.length)previewEmployee=data.employees[0].id;const e=connected?me:data.employees.find(x=>x.id===previewEmployee);if(!e){shell(heading('A little clarity. A better working day.','A focused space for your progress, breaks and daily handover.')+`<section class="welcome-card"><div class="welcome-icon">↗</div><h2>Your day, in one place.</h2><p>Start work. Share progress. Close the loop.<br>One simple daily thread for every department.</p><div class="row"><button class="btn primary" id="welcomeSample">Explore a sample day →</button><button class="btn" id="welcomeSetup">Pilot setup</button></div><div class="welcome-steps"><span>01 &nbsp; Sign in</span><span>02 &nbsp; Mid-day</span><span>03 &nbsp; EOD & sign out</span></div></section>`);document.querySelector('#welcomeSample').onclick=()=>{loadSample();render()};document.querySelector('#welcomeSetup').onclick=pilotTools;return}const active=data.sessions.find(x=>x.employee_id===e.id&&!x.ended_at),today=localDate(now(),e.timezone);submissionDate=active?active.work_date:today;const day=submissionDate;if(!updateTab)updateTab=data.updates.some(x=>x.employee_id===e.id&&x.work_date===day&&x.kind==='midday')||data.exceptions.some(x=>x.employee_id===e.id&&x.work_date===day)?'eod':'midday';const w=data.sessions.find(x=>x.employee_id===e.id&&x.work_date===day),st=status(e,day,updateTab,data,now()),u=data.updates.find(x=>x.employee_id===e.id&&x.work_date===day&&x.kind===updateTab),ex=data.exceptions.find(x=>x.employee_id===e.id&&x.work_date===day),draft=getDraft(e.id,day,updateTab),body={...u,...draft};shell(heading('Make today’s progress clear.','One daily thread. A shared view of what moves forward.',`<div class="date-context"><div><span id="calendarLabel">${longDate(day)}</span><b id="wallClock">${clockText(e.timezone)}</b></div><span class="timezone-chip">${esc(e.timezone)} · ${offsetText(e.timezone)}</span></div>`)+sessionPanel(e,w,day)+`<div class="day-layout"><section class="panel update-composer"><div class="composer-header"><div><div class="eyebrow">SHARE YOUR PROGRESS</div><h2>Your daily update</h2></div><span id="draftState" class="sub">${draft?'Draft saved on this device':u?'Submitted · Revision '+(u.version||1):'Ready when you are'}</span></div><div class="checkpoint-tabs">${['midday','eod'].map(k=>`<button data-update-tab="${k}" class="${k===updateTab?'selected':''}"><span>${k==='midday'?'01':'02'}</span><div><b>${k==='midday'?'Mid-day update':'End-of-day update'}</b><small>${k==='midday'?'Around 4 working hours':'30–45 min before signing out'}</small></div>${badge(status(e,day,k,data,now()))}</button>`).join('')}</div><div class="composer-body">${updateTab==='midday'?`<p class="form-intro">A quick snapshot of completed work, what’s next and where you need support.</p>`:`<div class="handover-note"><span>↗</span><p><b>Leave a clear handover.</b> Submit before you finish, then stay available for 30–45 minutes for feedback. Working beyond 8 hours? Your timer keeps counting.</p></div>`}<form data-update="${updateTab}" data-employee="${e.id}" id="dailyUpdateForm"><label>Completed tasks & progress <span class="required-mark">*</span></label><p class="field-help">One task per line. Include the outcome or current status.</p><textarea name="progress" class="task-area" required minlength="10" maxlength="6000" placeholder="• Completed…&#10;• Progressed…&#10;• Reviewed…" ${!w||st==='Exempt'?'disabled':''}>${esc(body.progress||'')}</textarea><label>Work links & evidence <span class="optional">Optional</span></label><p class="field-help">ClickUp, GitHub, Figma, Docs, campaigns, QA evidence or screenshot links.</p><textarea name="work_links" class="links-area" maxlength="6000" placeholder="https://… (one link per line)" ${!w||st==='Exempt'?'disabled':''}>${esc(body.work_links||'')}</textarea><div class="composer-two"><div><label>Next priorities / remaining work <span class="required-mark">*</span></label><textarea name="next_steps" required minlength="5" maxlength="4000" placeholder="What happens next?" ${!w||st==='Exempt'?'disabled':''}>${esc(body.next_steps||'')}</textarea></div><div><label>Blockers / help needed <span class="required-mark">*</span></label><textarea name="blockers" required minlength="3" maxlength="2000" placeholder="No blockers, or describe the issue." ${!w||st==='Exempt'?'disabled':''}>${esc(body.blockers||'')}</textarea></div></div><label>Support person / reporting manager <span class="optional">If blocked</span></label><input name="support_person" maxlength="300" placeholder="Who can help resolve this?" value="${esc(body.support_person||'')}" ${!w||st==='Exempt'?'disabled':''}><div class="composer-actions"><div>${updateTab==='midday'&&!u&&st!=='Exempt'?`<button class="text-button" id="middayReason" type="button" ${!w?'disabled':''}>Can’t give a Mid-day update?</button>`:'<span class="sub">Your work, clearly documented.</span>'}</div><button class="btn primary" ${!w||st==='Exempt'?'disabled':''}>${u?'Save revision':'Submit '+(updateTab==='midday'?'Mid-day':'EOD')} <span>↗</span></button></div></form>${ex&&updateTab==='midday'?`<div class="note">Mid-day note: ${esc(ex.reason)}<br>Review: ${esc(ex.status)}${ex.review_note?' · '+esc(ex.review_note):''}</div>`:''}</div></section><aside class="day-aside">${dayLog(e,w,day)}${summaryCard(w,day)}<div class="quiet-note">One thread for every role. Links and evidence follow your work—not your department.</div></aside></div>`);document.querySelectorAll('[data-update-tab]').forEach(b=>b.onclick=()=>{updateTab=b.dataset.updateTab;render()});document.querySelectorAll('[data-work]').forEach(b=>b.onclick=()=>workAction(b.dataset.work,e));document.querySelector('#middayReason')?.addEventListener('click',()=>exceptionForm(e,day));document.querySelector('#dayPicker')?.addEventListener('change',ev=>{submissionDate=ev.target.value;render()});const form=document.querySelector('#dailyUpdateForm');form?.addEventListener('input',()=>{saveDraft(e.id,day,updateTab,Object.fromEntries(new FormData(form)));document.querySelector('#draftState').textContent='Draft saved on this device'});document.querySelectorAll('[data-log-record]').forEach(b=>b.onclick=()=>viewRecord(b.dataset.logRecord));bindNotification()}
function fmt(t){return new Intl.DateTimeFormat('en-GB',{dateStyle:'medium',timeStyle:'short',hour12:true,timeZone:me.timezone||'Asia/Dhaka'}).format(new Date(t))}
function history(){const us=data.updates.filter(u=>u.employee_id===(connected?me.id:previewEmployee)).sort((a,b)=>b.submitted_at.localeCompare(a.submitted_at));shell(heading('Your progress, over time.','Your submissions and revisions in one place.')+`<section class="panel"><div class="panel-head"><h2>My update history</h2><span class="pill">${us.length} submissions</span></div><div class="inner">${us.map(u=>`<div class="record"><div class="row"><b>${u.work_date} · ${u.kind==='midday'?'Mid-day':'End-of-day'}</b>${badge('Submitted')}</div><small>${fmt(u.submitted_at)} · Revision ${u.version||1}</small><p>${esc(u.progress)}</p><button class="text-button" data-record="${u.id}">Read full update →</button></div>`).join('')||'<div class="empty">Your first update will appear here.</div>'}</div></section>`)}
function employees(){shell(heading('The people behind the progress.','Add your employee data and manage access. No fixed shifts or late tracking.',`<button class="btn primary" id="addEmployee">+ Add employee</button>`)+`<section class="panel"><table class="data-table"><thead><tr><th>Employee</th><th>Email</th><th>Timezone</th><th>Access</th><th></th></tr></thead><tbody>${data.employees.map(e=>`<tr><td>${person(e)}</td><td data-label="Email">${esc(e.email)}</td><td data-label="Timezone">${esc(e.timezone)}</td><td data-label="Access">${badge(e.active?e.role==='hr'?'HR admin':'Active':'Inactive')}</td><td><button class="text-button" data-edit="${e.id}">Edit →</button></td></tr>`).join('')}</tbody></table></section><div class="note">Adding an employee authorizes their email. In Supabase Authentication, invite that same email to create their account. Public self-signup should remain disabled.</div>`)}
function reports(){if(!myTeam())return;if(!reportAnchor)reportAnchor=date;const from=reportPeriod==='month'?reportAnchor.slice(0,7)+'-01':weekStart(reportAnchor),to=reportPeriod==='month'?dateAdd(reportAnchor.slice(0,7)+'-01',32).slice(0,7)+'-01':dateAdd(from,6),end=reportPeriod==='month'?dateAdd(to,-1):to;const capped=end>localDate(now())?localDate(now()):end;shell(heading('A clearer view over time.','Weekly detail. Monthly perspective. Every update stays connected.',`<div class="period-pills"><button data-period="week" class="${reportPeriod==='week'?'active':''}">Weekly</button><button data-period="month" class="${reportPeriod==='month'?'active':''}">Monthly</button></div>`)+`<section class="panel"><div class="panel-head"><div><h2>${reportPeriod==='month'?'Monthly report · week by week':'Weekly report'}</h2><p>Working time, breaks, extra time and update records.</p></div><div class="row"><input id="reportAnchor" type="${reportPeriod==='month'?'month':'date'}" value="${reportPeriod==='month'?reportAnchor.slice(0,7):reportAnchor}" aria-label="Report period"><select id="reportEmployee" aria-label="Report employee"><option value="all">All employees</option>${data.employees.map(e=>`<option value="${e.id}" ${reportEmployee===e.id?'selected':''}>${esc(e.full_name)}</option>`).join('')}</select></div></div><div id="reportResult"></div></section><p class="report-subtitle">Current periods are provisional. Leave exclusions depend on the HR portal connection. Recorded hours are not a measure of productivity.</p>`);document.querySelectorAll('[data-period]').forEach(b=>b.onclick=()=>{reportPeriod=b.dataset.period;render()});document.querySelector('#reportAnchor').onchange=ev=>{reportAnchor=reportPeriod==='month'?ev.target.value+'-01':ev.target.value;render()};document.querySelector('#reportEmployee').onchange=ev=>{reportEmployee=ev.target.value;render()};if(from<=capped)generateReport(from,capped);else document.querySelector('#reportResult').innerHTML='<div class="report-empty">No records for this future period.</div>'}
function settings(){shell(heading('Daily updates. Kept simple.','A standalone GitHub-ready tracker for a remote team.')+`<div class="grid2"><section class="panel form-panel"><h2>Workspace</h2><label>Database</label><p>${connected?'Connected to your Supabase project':'Setup preview · No database connected'}</p><label>Employee data</label><p>${data.employees.length} employee record(s). Your roster can be added when ready.</p><label>HR portal</label><p>${cfg.hrPortalUrl?`<a href="${esc(safeUrl(cfg.hrPortalUrl))}" target="_blank" rel="noopener">Open existing HR portal ↗</a>`:'Add the existing HR portal URL in config.js.'}</p></section><section class="panel form-panel"><h2>Tracking policy</h2><label>Flexible working</label><p>Flexible work sign-in. Mid-day becomes due at 4 net hours and EOD at 8 net hours. Breaks pause the clock. No late-start penalty.</p><label>Leave</label><p>Leave requests and approvals stay in your existing HR portal. No separate leave-management page. Exclusion requires approved data imported from that portal; no connection is configured yet.</p><label>Reminders</label><p>In-app checkpoint notices and optional browser notifications while the page is open. No email reminders are configured.</p></section></div><section class="panel form-panel"><h2>GitHub launch</h2><p>Upload the GitHub-ready package → connect Supabase → invite HR and employees → enable GitHub Pages. Employee records remain empty until you add your data.</p><div class="spacer"></div><button class="btn" id="setup">View setup instructions</button>${!connected?'<button class="btn" id="clearPreview" style="margin-left:10px">Clear preview test data</button>':''}</section>`)}
function safeUrl(u){try{const x=new URL(u);return ['https:','http:'].includes(x.protocol)?x.href:'#'}catch{return '#'}}
function render(){if(!myTeam()&&['overview','reports'].includes(page)||!myHR()&&['employees','sessions','reviews','settings'].includes(page))page='updates';({overview,updates,history,employees,sessions,reviews,reports,settings}[page]||updates)()}
function showDialog(html){modal.innerHTML='<button class="close" aria-label="Close dialog">×</button>'+html;modal.querySelector('.close').onclick=()=>modal.close();associateLabels(modal);if(!modal.open)modal.showModal()}
function setup(){showDialog(`<h2>Connect your workspace</h2><div class="spacer"></div><p>This preview uses an empty employee roster. For shared, secure employee tracking:</p><ol style="line-height:2;color:#667563"><li>Create your Supabase project.</li><li>Obtain the reviewed private standalone database package; SQL installers are excluded from this company handoff.</li><li>Disable public signup and invite your HR account.</li><li>Ask the authorized database owner to create the first HR profile. Company integration needs a separate Django implementation.</li><li>Fill the public project URL and publishable/anon key in <code>config.js</code>.</li><li>The repository workflow publishes only website files to GitHub Pages.</li></ol><p>No service-role key belongs in the website. Full setup and verification steps are included in the source package.</p>`)}
async function load(){const {data:t,error:te}=await db.rpc('server_time');if(te)throw te;serverOffset=new Date(t).getTime()-Date.now();const tables=['employees','updates','leaves','holidays','work_sessions','midday_exceptions','session_events'];const results=await Promise.all(tables.map(async t=>{const rows=[];for(let offset=0;;offset+=500){const {data:batch,error}=await db.from(t).select('*').order('id').range(offset,offset+499);if(error)throw error;rows.push(...batch);if(batch.length<500)break}return rows}));results.forEach((r,i)=>data[({'work_sessions':'sessions','midday_exceptions':'exceptions','session_events':'sessionEvents'})[tables[i]]||tables[i]]=r);me=data.employees.find(e=>e.email.toLowerCase()===session.user.email.toLowerCase());if(!me||!me.active)throw new Error('Your account is not authorized. Ask HR to add or activate your employee profile.');}
async function write(table,payload,id){if(connected){let q=id?db.from(table).update(payload).eq('id',id):db.from(table).insert(payload);const {error}=await q;if(error)throw error;await load()}else{if(id)Object.assign(data[table].find(x=>x.id===id),payload);else data[table].push({id:demoId(),...payload});persist()}}
async function action(fn){if(busy)return;busy=true;const buttons=[...document.querySelectorAll('form button:not(:disabled)')];buttons.forEach(b=>b.disabled=true);try{await fn()}catch(e){toast(e.message||'Something went wrong. Please try again.')}finally{busy=false;buttons.forEach(b=>{if(b.isConnected)b.disabled=false})}}
function associateLabels(root=document){root.querySelectorAll('label').forEach(l=>{let el=l.nextElementSibling;while(el&&!['INPUT','SELECT','TEXTAREA','LABEL'].includes(el.tagName))el=el.nextElementSibling;if(el&&['INPUT','SELECT','TEXTAREA'].includes(el.tagName)){if(!el.id)el.id='field-'+Math.random().toString(36).slice(2);l.htmlFor=el.id}})}
function bind(){associateLabels();bindNotification();document.querySelector('#clearPreview')?.addEventListener('click',()=>{data={employees:[],updates:[],leaves:[],holidays:[],sessions:[],exceptions:[],sessionEvents:[]};previewEmployee='';previewSample=false;persist();render();toast('Preview test data cleared. Your real database is unchanged.')});document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{page=b.dataset.page;render()});document.querySelector('#setup')?.addEventListener('click',setup);document.querySelector('#signout').onclick=async()=>{clearAllDrafts();if(connected)await db.auth.signOut();session=null;login()};document.querySelector('#date')?.addEventListener('change',e=>{date=e.target.value||localDate(now());render()});document.querySelector('#search')?.addEventListener('input',e=>{search=e.target.value;const pos=e.target.selectionStart;overview();const el=document.querySelector('#search');el.focus();el.setSelectionRange(pos,pos)});['filter','team'].forEach(n=>document.querySelector('#'+n)?.addEventListener('change',e=>{if(n==='filter')filter=e.target.value;else team=e.target.value;render()}));document.querySelector('#export')?.addEventListener('click',()=>download('bevy-daily-'+date+'.csv',[['Employee','Email','Department','Work date','Mid-day','EOD','Overall','Recorded time','Session status','Mid-day reason','HR decision'],...employeeRows().map(r=>{const w=data.sessions.find(x=>x.employee_id===r.e.id&&x.work_date===date),ex=data.exceptions.find(x=>x.employee_id===r.e.id&&x.work_date===date);return [r.e.full_name,r.e.email,r.e.department,date,r.a,r.b,r.o,duration(sessionSeconds(w,now())),hoursLabel(w,now()),ex?.reason||'',ex?.status||'']})]));document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>viewEmployee(b.dataset.view));document.querySelectorAll('[data-record]').forEach(b=>b.onclick=()=>viewRecord(b.dataset.record));document.querySelectorAll('[data-update]').forEach(f=>f.onsubmit=e=>{e.preventDefault();action(async()=>{const p=Object.fromEntries(new FormData(f));Object.keys(p).forEach(k=>p[k]=p[k].trim());if(p.progress.length<10||p.next_steps.length<5||p.blockers.length<3)throw new Error('Please complete all three fields with meaningful detail.');const employee=connected?me:data.employees.find(x=>x.id===f.dataset.employee);const k=f.dataset.update,day=submissionDate||workDate(employee,now());if(!data.sessions.some(x=>x.employee_id===employee.id&&x.work_date===day))throw new Error('Sign in to your working day first.');if(k==='eod'&&required(employee,day,'midday',data.leaves,data.holidays)&&!data.updates.some(x=>x.employee_id===employee.id&&x.work_date===day&&x.kind==='midday')&&!data.exceptions.some(x=>x.employee_id===employee.id&&x.work_date===day&&x.status!=='declined'))throw new Error('Submit Mid-day or record a reason before EOD.');if(connected){const {error}=await db.rpc('submit_update',{p_work_date:day,p_kind:k,p_progress:p.progress,p_next_steps:p.next_steps,p_blockers:p.blockers,p_work_links:p.work_links||'',p_support_person:p.support_person||''});if(error)throw error;await load()}else{const u=data.updates.find(u=>u.employee_id===employee.id&&u.work_date===day&&u.kind===k);if(u){data.localVersions=data.localVersions||[];data.localVersions.push({...u,update_id:u.id,archived_at:now().toISOString()});Object.assign(u,p,{updated_at:now().toISOString(),version:(u.version||1)+1,session_seconds_at_submit:sessionSeconds(data.sessions.find(x=>x.employee_id===employee.id&&x.work_date===day),now())})}else data.updates.push({session_seconds_at_submit:sessionSeconds(data.sessions.find(x=>x.employee_id===employee.id&&x.work_date===day),now()),id:demoId(),employee_id:employee.id,work_date:day,kind:k,...p,submitted_at:now().toISOString(),updated_at:now().toISOString(),version:1});persist()}clearDraft(employee.id,day,k);toast('Update saved successfully.');render()})});document.querySelector('#addEmployee')?.addEventListener('click',()=>employeeForm());document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>employeeForm(data.employees.find(e=>e.id===b.dataset.edit)));document.querySelector('#reportForm')?.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target);generateReport(f.get('from'),f.get('to'))})}
function download(name,rows){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([csv(rows)],{type:'text/csv;charset=utf-8'}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function recordHTML(u){return `<div class="record"><div class="row"><b>${esc(u.work_date)} · ${u.kind==='midday'?'Mid-day':'End-of-day'}</b>${badge('Submitted')}</div><small>First submitted ${fmt(u.submitted_at)} · Revision ${u.version||1}</small><label>Progress / outcomes</label><p>${esc(u.progress)}</p><label>Next steps</label><p>${esc(u.next_steps)}</p><label>Blockers</label><p>${esc(u.blockers)}</p>${u.work_links?'<label>Work links & evidence</label><p>'+renderLinks(u.work_links)+'</p>':''}${u.support_person?'<label>Support person</label><p>'+esc(u.support_person)+'</p>':''}</div>`}
function viewEmployee(id){if(!myTeam()&&id!==me?.id)return;const e=data.employees.find(e=>e.id===id),us=data.updates.filter(u=>u.employee_id===id&&u.work_date===date);showDialog(`<h2>${esc(e.full_name)}</h2><p>${date} · ${esc(e.timezone)}</p>${employeeContext(e,date)}${us.map(u=>recordHTML(u)+`<button class="text-button" data-modal-record="${u.id}">Revision history →</button>`).join('')||'<div class="empty">No updates submitted for this work date.</div>'}`);modal.querySelectorAll('[data-modal-record]').forEach(b=>b.onclick=()=>viewRecord(b.dataset.modalRecord))}
function viewRecord(id){const u=data.updates.find(u=>u.id===id);if(!u||(!myTeam()&&u.employee_id!==(connected?me?.id:previewEmployee)))return;showDialog(recordHTML(u)+`<div id="revisions"></div>`);if(!connected){const el=modal.querySelector('#revisions');const vs=(data.localVersions||[]).filter(v=>v.update_id===id);if(el&&vs.length)el.innerHTML='<label>Previous revisions</label>'+vs.map(v=>'<div class="record"><small>Revision '+v.version+'</small><p>'+esc(v.progress)+'</p></div>').join('')}const revisionTarget=modal.querySelector('#revisions');if(connected)db.from('update_versions').select('*').eq('update_id',id).order('version',{ascending:false}).then(({data:vs,error})=>{if(error){toast(error.message);return}const el=revisionTarget;if(el?.isConnected&&modal.contains(el))el.innerHTML=vs.length?'<label>Previous revisions</label>'+vs.map(v=>`<div class="record"><small>Revision ${v.version} · ${fmt(v.archived_at)}</small><p>${esc(v.progress)}</p><p>${esc(v.next_steps)}</p><p>${esc(v.blockers)}</p></div>`).join(''):''})}
function employeeForm(e){showDialog(`<h2>${e?'Edit employee':'Add employee'}</h2><form id="employeeForm"><label>Full name</label><input name="full_name" required maxlength="120" value="${esc(e?.full_name||'')}"><label>Company email</label><input name="email" type="email" required value="${esc(e?.email||'')}"><div class="grid2"><div><label>Department</label><input name="department" required value="${esc(e?.department||'')}"></div><div><label>Country</label><input name="country" required value="${esc(e?.country||'Bangladesh')}"></div></div><div class="grid2"><div><label>Join date</label><input name="join_date" type="date" required value="${e?.join_date||date}"></div><div><label>Last working date (optional)</label><input name="end_date" type="date" value="${e?.end_date||''}"></div></div><label>Timezone (for calendar date only)</label><select name="timezone">${['Asia/Dhaka','Asia/Karachi','America/Toronto','UTC'].map(t=>`<option ${e?.timezone===t?'selected':''}>${t}</option>`).join('')}</select><label>Working days</label><div class="checks">${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map((d,i)=>`<label><input class="check" type="checkbox" name="day" value="${i}" ${(e?.workdays||[1,2,3,4,5]).includes(i)?'checked':''}> ${d}</label>`).join('')}</div><div class="grid2"><div><label>Role</label><select name="role"><option value="employee">Employee</option><option value="hr" ${e?.role==='hr'?'selected':''}>HR administrator</option><option value="management" ${e?.role==='management'?'selected':''}>Manager (own records only)</option></select></div><div><label>Account status</label><select name="active"><option value="true">Active</option><option value="false" ${e?.active===false?'selected':''}>Inactive</option></select></div></div><div class="spacer"></div><button class="btn primary">Save employee</button></form>`);document.querySelector('#employeeForm').onsubmit=ev=>{ev.preventDefault();action(async()=>{const f=new FormData(ev.target),p=Object.fromEntries(f);p.workdays=f.getAll('day').map(Number);delete p.day;p.email=p.email.trim().toLowerCase();p.active=p.active==='true';p.end_date=p.end_date||null;if(!p.workdays.length)throw new Error('Choose working days.');if(p.end_date&&p.end_date<p.join_date)throw new Error('Last working date must follow the join date.');if(e?.id===me.id&&(!p.active||p.role!=='hr'||p.email!==me.email))throw new Error('You cannot remove your own HR access.');await write('employees',p,e?.id);modal.close();toast(connected?'Employee saved. Invite new users in Supabase Authentication.':'Preview employee saved in this browser only.');render()})}}
function generateReport(from,to){if(!myTeam())return;const employees=data.employees.filter(e=>reportEmployee==='all'||e.id===reportEmployee),buckets=reportBuckets(employees,data,from,to,now()),weeks=[...new Set(buckets.map(b=>b.week))],sum=(k)=>buckets.reduce((n,b)=>n+b[k],0);const rows=[['Employee','Email','Week starting','Period from','Period to','Required updates','Mid-day submitted','EOD submitted','Mid-day notes pending','Mid-day excused','Recorded work','Break time','Beyond 8 hours','8h reached days','Review days'],...buckets.map(b=>[b.employee.full_name,b.employee.email,b.week,from,to,b.midRequired+b.eodRequired,b.midday,b.eod,b.reason,b.excused,hms(b.seconds),hms(b.breaks),hms(b.extra),b.hoursMet,b.review])];document.querySelector('#reportResult').innerHTML=`<div class="toolbar" style="justify-content:space-between"><span class="sub">${shortDate(from)} – ${shortDate(to)}</span><div class="row"><button class="btn" id="reportDetail">↓ Export daily detail</button><button class="btn primary" id="reportExport">↓ Export weekly summary</button></div></div><div class="stats" style="padding:0 21px">${[[hms(sum('seconds')),'Recorded work'],[hms(sum('breaks')),'Break time'],[sum('midday')+sum('eod'),'Updates submitted'],[sum('review'),'Notes / review items']].map(([n,l])=>`<div class="stat"><div class="label">${l}</div><div class="num" style="font-size:22px">${n}</div></div>`).join('')}</div>${weeks.map(week=>`<div class="week-title">Week of ${shortDate(week)} <span style="font-weight:400">· ${shortDate(week<from?from:week)} – ${shortDate(dateAdd(week,6)>to?to:dateAdd(week,6))}</span></div><div style="overflow:auto"><table><thead><tr><th>Employee</th><th>Working time</th><th>Breaks</th><th>Beyond 8h</th><th>Updates</th><th>Mid-day notes</th><th>Review</th></tr></thead><tbody>${buckets.filter(b=>b.week===week).map(b=>`<tr><td>${person(b.employee)}</td><td>${hms(b.seconds)}</td><td>${hms(b.breaks)}</td><td>${hms(b.extra)}</td><td>${b.midday+b.eod} / ${b.midRequired+b.eodRequired}</td><td>${b.reason} pending · ${b.excused} excused</td><td>${b.review}</td></tr>`).join('')}</tbody></table></div>`).join('')||'<div class="report-empty">No employee data yet. Reports populate from recorded workdays and updates.</div>'}`;document.querySelector('#reportExport').onclick=()=>download(`bevy-weekly-summary-${from}-${to}.csv`,rows);document.querySelector('#reportDetail').onclick=()=>{const raw=[['Employee','Work date','Timezone','Start','End','Net work','Break time','Beyond 8 hours','Mid-day status','EOD status','Mid-day tasks','EOD tasks','Evidence links','Blockers','Mid-day note','HR decision','Closing note']];for(const e of employees)for(let d=from;d<=to;d=dateAdd(d,1)){if(!required(e,d,'eod',data.leaves,data.holidays))continue;const w=data.sessions.find(w=>w.employee_id===e.id&&w.work_date===d),mid=data.updates.find(u=>u.employee_id===e.id&&u.work_date===d&&u.kind==='midday'),end=data.updates.find(u=>u.employee_id===e.id&&u.work_date===d&&u.kind==='eod'),ex=data.exceptions.find(x=>x.employee_id===e.id&&x.work_date===d);raw.push([e.full_name,d,e.timezone,w?.started_at||'',w?.ended_at||'',hms(sessionSeconds(w,now())),hms(breakSeconds(w,now())),hms(Math.max(0,sessionSeconds(w,now())-28800)),status(e,d,'midday',data,now()),status(e,d,'eod',data,now()),mid?.progress||'',end?.progress||'',end?.work_links||mid?.work_links||'',end?.blockers||mid?.blockers||'',ex?.reason||'',ex?.status||'',w?.close_reason||''])}download(`bevy-daily-detail-${from}-${to}.csv`,raw)}}
function login(){app.innerHTML=`<div class="login-wrap"><div class="login-art"><div class="brand" style="color:#fff;padding:0">bevy<span>•</span></div><div><div class="eyebrow" style="color:#a3bd8b">DAILY UPDATES</div><h1>Small updates.<br>Shared momentum.</h1><p>A simple space to share progress, surface blockers and keep every working day clear.</p></div><p style="font-size:11px">BEVY COMMERCE · PEOPLE & CULTURE</p></div><div class="login-box"><form id="login"><div class="eyebrow">YOUR WORKSPACE</div><h1>Welcome back.</h1><p>Sign in with your invited work account.</p><label>Email address</label><input name="email" autocomplete="username" type="email" required placeholder="you@bevycommerce.com"><label>Password</label><input name="password" autocomplete="current-password" type="password" minlength="8" required placeholder="Your password"><button class="btn primary">Sign in →</button><div class="login-error" role="alert" id="loginError"></div><div class="spacer"></div>${connected?'<button type="button" class="text-button" id="reset">Forgot password / set invited account password</button>':'<p class="sub">Database not connected.</p><button type="button" class="btn" id="demo">Explore interactive demo →</button>'}</form></div></div>`;associateLabels();document.querySelector('#demo')?.addEventListener('click',()=>{demo();page='overview';render()});document.querySelector('#login').onsubmit=ev=>{ev.preventDefault();if(!connected){toast('Connect your database first, or explore the demo.');return}action(async()=>{const f=new FormData(ev.target);const {data:r,error}=await db.auth.signInWithPassword({email:f.get('email'),password:f.get('password')});if(error){document.querySelector('#loginError').textContent=error.message;return}session=r.session;try{await load();page=myHR()?'overview':'updates';render()}catch(e){await db.auth.signOut();session=null;document.querySelector('#loginError').textContent=e.message}})};document.querySelector('#reset')?.addEventListener('click',()=>action(async()=>{const email=document.querySelector('[name=email]').value;if(!email)throw new Error('Enter your invited email first.');const {error}=await db.auth.resetPasswordForEmail(email,{redirectTo:location.origin+location.pathname});if(error)throw error;toast('If the account exists, a password setup email will arrive shortly.')}))}
function passwordSetup(){app.innerHTML='<div class="login-box" style="min-height:100vh"><form id="setPassword"><h1>Set your password.</h1><p>Use at least 12 characters.</p><label>New password</label><input type="password" name="password" minlength="12" required autocomplete="new-password"><button class="btn primary">Save password</button></form></div>';associateLabels();document.querySelector('#setPassword').onsubmit=ev=>{ev.preventDefault();action(async()=>{const {error}=await db.auth.updateUser({password:new FormData(ev.target).get('password')});if(error)throw error;window.history.replaceState(null,'',location.pathname);toast('Password saved.');await load();page=myHR()?'overview':'updates';render()})}}
async function boot(){if(!connected){demo();if(new URLSearchParams(location.search).get('preview')==='pm')loadSample();page='updates';render();return}app.innerHTML='<div class="empty">Opening your workspace…</div>';try{const authFlow=location.hash.includes('type=recovery')||location.hash.includes('type=invite');const {createClient}=await import('https://esm.sh/@supabase/supabase-js@2.49.8');db=createClient(cfg.supabaseUrl,cfg.supabaseAnonKey);const recovery=authFlow;const {data:r}=await db.auth.getSession();session=r.session;db.auth.onAuthStateChange((event,s)=>{session=s;if(event==='PASSWORD_RECOVERY')setTimeout(passwordSetup,0);if(event==='SIGNED_OUT')login()});if(session){if(recovery){passwordSetup();return}await load();page=myHR()?'overview':'updates';render()}else login()}catch(e){login();const err=document.querySelector('#loginError');if(err)err.textContent=e.message}}
boot();setInterval(()=>{if(!session||!connected||busy||modal.open||document.querySelector('textarea:focus'))return;if(['overview','reviews','sessions'].includes(page))load().then(()=>{render()}).catch(()=>toast('Refresh failed. Data may be stale; please retry.'))},60000);

function bindPreviewPicker(){const p=document.querySelector('#previewEmployee');if(p)p.onchange=e=>{previewEmployee=e.target.value;submissionDate='';render()};}

function sessionPanel(e,w,day){const seconds=sessionSeconds(w,now()),br=breakSeconds(w,now()),elapsed=w?Math.max(0,(new Date(w.ended_at||now())-new Date(w.started_at))/1000):0,percent=Math.min(100,seconds/288),active=w&&!w.ended_at;return `<section class="work-card"><div class="work-card-top"><div><span class="live-indicator ${w?.paused_at?'paused':''}"></span><span class="work-label">${!w?'YOUR WORKING DAY':w.ended_at?'DAY CLOSED':w.paused_at?'ON A BREAK':'WORKING TIME'}</span></div><span class="work-date">${shortDate(day)} · ${esc(e.timezone)}</span></div><div class="work-card-body"><div class="timer-block"><div class="hero-timer" id="workClock">${hms(seconds)}</div><div class="timer-units"><span>HOURS</span><span>MINUTES</span><span>SECONDS</span></div><p>${w?'Signed in at '+timeText(w.started_at,e.timezone):'Start whenever your work begins.'}${w?.ended_at?' · Signed out at '+timeText(w.ended_at,e.timezone):''}</p></div><div class="time-metrics"><div><span>Break time</span><b id="breakClock">${hms(br)}</b><small>Automatically excluded</small></div><div><span>Total elapsed</span><b id="elapsedClock">${hms(elapsed)}</b><small>Work + breaks</small></div><div><span>Beyond 8 hours</span><b id="extraClock">${hms(Math.max(0,seconds-28800))}</b><small>Recorded separately</small></div></div><div class="work-controls">${!w?'<button class="btn timer-primary" data-work="start">Start my working day ↗</button>':active?`<button class="btn timer-primary" data-work="${w.paused_at?'resume':'pause'}">${w.paused_at?'▶ Resume work':'Ⅱ Take a break'}</button><button class="btn timer-secondary" data-work="end">Sign out of work ↗</button>`:'<span class="closed-chip">✓ Workday closed</span>'}<span class="work-target">${w&&seconds>=28800?'8-hour target reached · keep going if needed':'Daily target: 8 net working hours'}</span></div></div><div class="work-progress"><div class="progress-track"><i id="workProgress" style="width:${percent}%"></i><span class="mid-marker"></span></div><div class="progress-labels"><span>Sign in</span><span>4h · Mid-day</span><span>8h · Daily target</span></div></div>${staleSession(w,now())?'<div class="timer-review">This session needs HR review. Recorded hours remain visible.</div>':''}</section>`}
async function rpc(name,args){const {data:r,error}=await db.rpc(name,args);if(error)throw error;await load();return r}
function workAction(type,e){if(type==='pause'){breakForm(e);return}if(type==='short_day'){showDialog('<h2>Record a short working day</h2><p>The 8-hour requirement remains visible. HR will see the reason and recorded shortfall. Submit EOD next, then sign out.</p><form id="shortDayForm"><label>Reason</label><textarea name="reason" required minlength="10" maxlength="2000"></textarea><div class="spacer"></div><button class="btn primary">Record reason</button></form>');associateLabels(modal);document.querySelector('#shortDayForm').onsubmit=ev=>{ev.preventDefault();action(()=>doWork(type,e,new FormData(ev.target).get('reason')))};return}if(type==='end'){const w=data.sessions.find(x=>x.employee_id===e.id&&!x.ended_at);if(!w)return;if(!data.updates.some(x=>x.employee_id===e.id&&x.work_date===w.work_date&&x.kind==='eod')){updateTab='eod';render();toast('Share your EOD handover before signing out.');return}closingSummary(e,w);return}action(()=>doWork(type,e,''))}
async function doWork(type,e,note){if(connected)await rpc('work_action',{p_action:type,p_note:note});else{let w=data.sessions.find(x=>x.employee_id===e.id&&!x.ended_at),before=w?structuredClone(w):null;if(type==='start'){if(!w){const day=localDate(now(),e.timezone);if(!required(e,day,'eod',data.leaves,data.holidays))throw new Error('This date is exempt / not a configured workday.');if(data.sessions.some(x=>x.employee_id===e.id&&x.work_date===day))throw new Error('This workday is already closed.');w={id:demoId(),employee_id:e.id,work_date:day,started_at:now().toISOString(),ended_at:null,break_seconds:0,paused_at:null,needs_review:false};data.sessions.push(w)}}else if(!w)throw new Error('No active session.');else if(type==='pause')w.paused_at=w.paused_at||now().toISOString();else if(type==='resume'){if(w.paused_at)w.break_seconds+=Math.max(0,(now()-new Date(w.paused_at))/1000);w.paused_at=null}else if(type==='short_day'){w.close_reason=note;w.needs_review=true}else if(type==='end'){const latest=data.updates.find(u=>u.employee_id===e.id&&u.work_date===w.work_date&&u.kind==='eod');if(!latest)throw new Error('Submit your End-of-day update before signing out');w.needs_review=sessionSeconds(w,now())<28800||staleSession(w,now())||(latest.updated_at&&(now()-new Date(latest.updated_at))/1000<1800);if(w.needs_review&&String(note||'').trim().length<10)throw new Error('A short-day / forgotten-sign-out reason is required');if(w.paused_at)w.break_seconds+=(now()-new Date(w.paused_at))/1000;w.paused_at=null;w.ended_at=now().toISOString();w.close_reason=note||w.close_reason}data.sessionEvents.push({id:demoId(),session_id:w.id,employee_id:e.id,actor_id:e.id,action:type,note,snapshot:{before,after:structuredClone(w)},created_at:now().toISOString()});persist();submissionDate=w.work_date;if(type==='start')updateTab='midday'}if(modal.open)modal.close();toast(type==='start'?'Working day started.':type==='end'?'Work session closed.':type==='pause'?'Break started. Working time is paused.':type==='short_day'?'Short-day reason recorded. Submit EOD and sign out.':'Work resumed.');render()}
function exceptionForm(e,day){const prev=data.exceptions.find(x=>x.employee_id===e.id&&x.work_date===day);showDialog(`<h2>Unable to submit Mid-day?</h2><p>Record why it was missed. EOD is still required. HR can accept or decline the exception.</p><form id="exceptionForm"><label>Reason category</label><select name="category">${['Work pressure','Meeting or client call','Connectivity or power issue','Other'].map(x=>`<option ${prev?.category===x?'selected':''}>${x}</option>`).join('')}</select><label>Brief explanation</label><textarea name="reason" required minlength="10" maxlength="2000">${esc(prev?.reason||'')}</textarea><div class="spacer"></div><button class="btn primary">Submit reason for HR review</button></form>`);associateLabels(modal);document.querySelector('#exceptionForm').onsubmit=ev=>{ev.preventDefault();action(async()=>{const f=Object.fromEntries(new FormData(ev.target));f.reason=f.reason.trim();if(f.reason.length<10)throw new Error('Please add a short explanation.');if(connected)await rpc('submit_midday_exception',{p_work_date:day,p_category:f.category,p_reason:f.reason});else{if(prev)Object.assign(prev,f,{status:'pending',review_note:'',revision:(prev.revision||1)+1,submitted_at:now().toISOString(),reviewed_by:null,reviewed_at:null});else data.exceptions.push({id:demoId(),employee_id:e.id,work_date:day,...f,status:'pending',revision:1,submitted_at:now().toISOString()});persist()}modal.close();toast('Reason submitted. EOD is still required.');render()})}}
function reviews(){const pending=data.exceptions.filter(x=>!data.updates.some(u=>u.employee_id===x.employee_id&&u.work_date===x.work_date&&u.kind==='midday'));shell(heading('Context before conclusions.','Review Mid-day exceptions without hiding missed updates.')+`<section class="panel"><div class="panel-head"><h2>Mid-day exception requests</h2><span class="pill">${pending.filter(x=>x.status==='pending').length} pending</span></div><div class="inner">${pending.map(x=>`<div class="record"><div class="row" style="justify-content:space-between"><b>${esc(data.employees.find(e=>e.id===x.employee_id)?.full_name||'Employee')} · ${x.work_date}</b>${badge(x.status)}</div><label>${esc(x.category)}</label><p>${esc(x.reason)}</p>${x.review_note?`<p>HR: ${esc(x.review_note)}</p>`:''}<div class="spacer"></div><button class="btn" data-review="${x.id}">Review / change decision</button></div>`).join('')||'<div class="empty">No Mid-day exceptions to review.</div>'}</div></section>`);document.querySelectorAll('[data-review]').forEach(b=>b.onclick=()=>reviewForm(data.exceptions.find(x=>x.id===b.dataset.review)))}
function reviewForm(ex){const expectedRevision=ex.revision||1;showDialog(`<h2>Review Mid-day exception</h2><p>${esc(ex.reason)}</p><form id="reviewForm"><label>Decision</label><select name="status"><option value="accepted">Accept exception</option><option value="declined">Decline exception</option></select><label>Review note</label><textarea name="note" required minlength="5" maxlength="2000"></textarea><div class="spacer"></div><button class="btn primary">Save review</button></form>`);associateLabels(modal);document.querySelector('#reviewForm').onsubmit=ev=>{ev.preventDefault();action(async()=>{const f=Object.fromEntries(new FormData(ev.target));if(connected){try{await rpc('review_midday_exception',{p_id:ex.id,p_status:f.status,p_note:f.note,p_expected_revision:expectedRevision})}catch(error){if(/changed|stale/i.test(error.message)){await load();modal.close();render();throw new Error('The exception reason changed. Open it again and review the latest revision.')}throw error;}}else{const current=data.exceptions.find(x=>x.id===ex.id);if(!current||(current.revision||1)!==expectedRevision)throw new Error('The exception reason changed. Open it again.');Object.assign(current,{status:f.status,review_note:f.note,reviewed_at:now().toISOString(),reviewed_by:me.id});persist()}modal.close();render();toast('HR decision recorded.')})}}
function employeeContext(e,day){const w=data.sessions.find(x=>x.employee_id===e.id&&x.work_date===day),ex=data.exceptions.find(x=>x.employee_id===e.id&&x.work_date===day);return `<div class="note" style="margin-top:15px">${w?`Recorded work: ${duration(sessionSeconds(w,now()))} · ${hoursLabel(w,now())}<br>Start: ${fmt(w.started_at)}${w.ended_at?' · End: '+fmt(w.ended_at):''}${w.close_reason?'<br>Close note: '+esc(w.close_reason):''}`:'No work session recorded.'}${ex?'<br>Mid-day reason: '+esc(ex.category)+' — '+esc(ex.reason)+'<br>HR decision: '+esc(ex.status):''}</div>`}
function sessions(){shell(heading('Working time, with context.','Flexible sign-ins, breaks and recorded corrections.',`<button class="btn primary" id="correctSession">+ Record / correct session</button>`)+`<section class="panel"><div style="overflow:auto"><table class="data-table"><thead><tr><th>Employee / date</th><th>Started</th><th>Ended</th><th>Net time</th><th>Status</th><th></th></tr></thead><tbody>${[...data.sessions].sort((a,b)=>b.started_at.localeCompare(a.started_at)).map(w=>`<tr><td>${esc(data.employees.find(e=>e.id===w.employee_id)?.full_name)}<br><small>${w.work_date}</small></td><td data-label="Started">${fmt(w.started_at)}</td><td data-label="Ended">${w.ended_at?fmt(w.ended_at):'Open'}</td><td data-label="Net time">${duration(sessionSeconds(w,now()))}</td><td data-label="Status">${badge(hoursLabel(w,now()))}</td><td><button class="text-button" data-audit="${w.id}">Audit →</button><button class="text-button" data-correct="${w.id}">Correct →</button></td></tr>`).join('')||'<tr><td class="empty" colspan="6">No work sessions recorded yet.</td></tr>'}</tbody></table></div></section><div class="note">Closing an account session does not sign out of work. Open sessions older than 18 hours require review. HR corrections retain a reason and before/after values.</div>`);document.querySelector('#correctSession').onclick=()=>correctionForm();document.querySelectorAll('[data-correct]').forEach(b=>b.onclick=()=>correctionForm(data.sessions.find(x=>x.id===b.dataset.correct)));document.querySelectorAll('[data-audit]').forEach(b=>b.onclick=()=>sessionAudit(b.dataset.audit))}
function sessionAudit(id){const rows=data.sessionEvents.filter(x=>x.session_id===id).sort((a,b)=>b.created_at.localeCompare(a.created_at));showDialog('<h2>Session audit trail</h2>'+rows.map(x=>`<div class="record"><b>${esc(x.action)} · ${fmt(x.created_at)}</b><p>${esc(x.note)}</p><details><summary>Recorded before / after values</summary><pre style="white-space:pre-wrap;overflow-wrap:anywhere;font-size:11px">${esc(JSON.stringify(x.snapshot,null,2))}</pre></details></div>`).join(''))}
function correctionForm(w){showDialog(`<h2>${w?'Correct work session':'Record a missed sign-in'}</h2><p>Use UTC timestamps below. Changes are recorded in the audit trail. Use this for forgotten sign-ins / sign-outs after checking with the employee.</p><form id="correctionForm"><label>Employee</label><select name="employee_id" ${w?'disabled':''}>${data.employees.filter(e=>e.active).map(e=>`<option value="${e.id}" ${w?.employee_id===e.id?'selected':''}>${esc(e.full_name)} · ${esc(e.timezone)}</option>`).join('')}</select><label>Work date (employee timezone)</label><input type="date" name="work_date" required value="${w?.work_date||date}" ${w?'readonly':''}><label>Start time — UTC</label><input type="datetime-local" name="started_at" required value="${w?new Date(w.started_at).toISOString().slice(0,16):''}"><label>End time — UTC (blank = still working)</label><input type="datetime-local" name="ended_at" value="${w?.ended_at?new Date(w.ended_at).toISOString().slice(0,16):''}"><label>Total break minutes</label><input type="number" name="break_minutes" min="0" step="0.1" required value="${w?Math.round(Number(w.break_seconds)/6)/10:0}"><label>Correction reason</label><textarea name="reason" required minlength="10" maxlength="2000"></textarea><div class="spacer"></div><button class="btn primary">Save audited correction</button></form>`);associateLabels(modal);document.querySelector('#correctionForm').onsubmit=ev=>{ev.preventDefault();action(async()=>{const f=Object.fromEntries(new FormData(ev.target)),eid=w?.employee_id||f.employee_id,start=new Date(f.started_at+'Z'),end=f.ended_at?new Date(f.ended_at+'Z'):null,breaks=Number(f.break_minutes)*60;if(start>now()||(end&&(end<start||end>now()))||breaks<0||breaks>((end||now())-start)/1000)throw new Error('Please check start, end and break times.');if(connected)await rpc('correct_work_session',{p_employee_id:eid,p_work_date:f.work_date,p_started_at:start.toISOString(),p_ended_at:end?.toISOString()||null,p_break_seconds:breaks,p_reason:f.reason});else{const employee=data.employees.find(e=>e.id===eid);if(localDate(start,employee.timezone)!==f.work_date)throw new Error('Start must match the employee work date in their timezone.');if(!required(employee,f.work_date,'eod',data.leaves,data.holidays))throw new Error('Date is exempt / outside employment dates.');if(data.sessions.some(x=>x.employee_id===eid&&!x.ended_at&&x.id!==w?.id)&&!end)throw new Error('Employee already has an open session.');const prior=w||data.sessions.find(x=>x.employee_id===eid&&x.work_date===f.work_date),before=prior?structuredClone(prior):null,newValues={employee_id:eid,work_date:f.work_date,started_at:start.toISOString(),ended_at:end?.toISOString()||null,break_seconds:breaks,paused_at:null,needs_review:false,close_reason:f.reason};let current;if(prior){Object.assign(prior,newValues);current=prior}else{current={id:demoId(),...newValues};data.sessions.push(current)}data.sessionEvents.push({id:demoId(),session_id:current.id,employee_id:eid,actor_id:me.id,action:'hr_correction',note:f.reason,snapshot:{before,after:structuredClone(current)},created_at:now().toISOString()});persist()}modal.close();render();toast('Correction saved with audit history.')})}}
function bindNotification(){document.querySelector('#enableNotices')?.addEventListener('click',async()=>{if(!('Notification' in window)){toast('This browser does not support notifications.');return}const permission=await Notification.requestPermission();toast(permission==='granted'?'Checkpoint notifications enabled while this page is open.':'Use the in-app checkpoint notices instead.')})}
function longDate(d){return new Intl.DateTimeFormat('en-GB',{weekday:'long',day:'numeric',month:'long',year:'numeric',timeZone:'UTC'}).format(new Date(d+'T12:00:00Z'))}
function shortDate(d){return new Intl.DateTimeFormat('en-GB',{day:'2-digit',month:'short',year:'numeric',timeZone:'UTC'}).format(new Date(d+'T12:00:00Z'))}
function timeText(t,tz=me?.timezone||'Asia/Dhaka'){return new Intl.DateTimeFormat('en-GB',{hour:'2-digit',minute:'2-digit',hour12:true,timeZone:tz}).format(new Date(t))}
function clockText(tz){return zonedClock(now(),tz).time}
function offsetText(tz){return new Intl.DateTimeFormat('en-GB',{timeZone:tz,timeZoneName:'shortOffset'}).formatToParts(now()).find(x=>x.type==='timeZoneName').value.replace('GMT','UTC')}
function draftKey(e,d,k){return 'bevy-draft:'+e+':'+d+':'+k}
function getDraft(e,d,k){try{return JSON.parse(sessionStorage.getItem(draftKey(e,d,k))||'null')}catch{return null}}
function saveDraft(e,d,k,v){try{sessionStorage.setItem(draftKey(e,d,k),JSON.stringify(v))}catch{toast('This browser could not save your draft. Please submit before closing.')}}
function clearDraft(e,d,k){sessionStorage.removeItem(draftKey(e,d,k))}
function clearAllDrafts(){Object.keys(sessionStorage).filter(x=>x.startsWith('bevy-draft:')).forEach(x=>sessionStorage.removeItem(x))}
function pilotTools(){if(!myHR())return;showDialog(`<div class="eyebrow">PILOT ADMINISTRATION</div><h2>Keep the daily module focused.</h2><p>These tools support a standalone pilot. Employee profiles, access and leave can be supplied by the HR portal in the integrated version.</p><div class="pilot-tools">${[['employees','Employee roster','Add the pilot roster when ready.'],['sessions','Session corrections','Review missed sign-ins and clock history.'],['reviews','Mid-day notes','Review recorded exceptions.'],['settings','Connection & policy','Database setup and integration details.']].map(([p,t,d])=>`<button data-tool="${p}"><b>${t} ↗</b><span>${d}</span></button>`).join('')}</div>`);modal.querySelectorAll('[data-tool]').forEach(b=>b.onclick=()=>{page=b.dataset.tool;modal.close();render()})}
function dayLog(e,w,day){const events=[];if(w)events.push({at:w.started_at,label:'Signed in',type:'start',note:`${day.slice(8)}/${day.slice(5,7)} — Signing in at ${timeText(w.started_at,e.timezone)} (${e.timezone})`});for(const x of data.sessionEvents.filter(x=>x.employee_id===e.id&&data.sessions.some(w=>w.id===x.session_id&&w.work_date===day))){if(x.action==='pause')events.push({at:x.created_at,label:'Break started',type:'break',note:x.note||'Working timer paused.'});if(x.action==='resume')events.push({at:x.created_at,label:'Back from break',type:'resume',note:'Working timer resumed.'})}for(const u of data.updates.filter(x=>x.employee_id===e.id&&x.work_date===day))events.push({at:u.submitted_at,label:u.kind==='midday'?'Mid-day shared':'EOD shared',type:'update',note:u.progress,record:u.id});const ex=data.exceptions.find(x=>x.employee_id===e.id&&x.work_date===day);if(ex&&!data.updates.some(x=>x.employee_id===e.id&&x.work_date===day&&x.kind==='midday'))events.push({at:ex.submitted_at,label:'Mid-day note recorded',type:'note',note:ex.reason+' · '+ex.status});if(w?.ended_at)events.push({at:w.ended_at,label:'Signed out',type:'end',note:`Net work ${hms(sessionSeconds(w,now()))} · Breaks ${hms(breakSeconds(w,now()))}${w.close_reason?' · '+w.close_reason:''}`});events.sort((a,b)=>a.at.localeCompare(b.at));return `<section class="panel day-log"><div class="aside-heading"><div><div class="eyebrow">THE DAILY THREAD</div><h2>Today’s activity</h2></div><span class="count-chip">${events.length}</span></div><div class="timeline">${events.map(x=>`<div class="timeline-item ${x.type}"><span class="timeline-dot"></span><div><div class="timeline-title"><b>${x.label}</b><time>${timeText(x.at,e.timezone)}</time></div><p>${esc(x.note.length>125?x.note.slice(0,122)+'…':x.note)}</p>${x.record?`<button class="text-button" data-log-record="${x.record}">View update ↗</button>`:''}</div></div>`).join('')||'<p class="empty">Your sign-in, breaks and updates appear here automatically.</p>'}${w&&!w.ended_at?`<div class="timeline-item current"><span class="timeline-dot"></span><div><b>${w.paused_at?'On a break':'Day in progress'}</b><p>${w.paused_at?'Resume when you return.':'Your next action keeps the thread up to date.'}</p></div></div>`:''}</div></section>`}
function summaryCard(w,day){return `<section class="summary-card"><div class="eyebrow">YOUR DAY AT A GLANCE</div><h2>${w?.ended_at?'Daily summary':'The full picture'}</h2><div class="summary-row"><span>Working time</span><b id="summaryWork">${hms(sessionSeconds(w,now()))}</b></div><div class="summary-row"><span>Break time</span><b id="summaryBreak">${hms(breakSeconds(w,now()))}</b></div><div class="summary-row"><span>Beyond 8 hours</span><b id="summaryExtra">${hms(Math.max(0,sessionSeconds(w,now())-28800))}</b></div><p>Breaks are excluded automatically. Work can continue beyond the 8-hour target.</p></section>`}
function loadSample(){const started=new Date(Date.now()-(10*3600+25*60)*1000),day=localDate(started,'Asia/Dhaka'),at=m=>new Date(started.getTime()+m*60000).toISOString();clearAllDrafts();data={isSample:true,employees:[{id:'sample-colleague',email:'sample@example.com',full_name:'Demo Colleague',department:'Cross-functional team',country:'Bangladesh',role:'employee',active:true,join_date:'2020-01-01',timezone:'Asia/Dhaka',workdays:[...new Set([1,2,3,4,5,new Date(day+'T12:00:00Z').getUTCDay()])]}],sessions:[{id:'sample-session',employee_id:'sample-colleague',work_date:day,started_at:started.toISOString(),ended_at:null,break_seconds:48*60,paused_at:null,needs_review:false}],updates:[{id:'sample-midday',employee_id:'sample-colleague',work_date:day,kind:'midday',progress:'• Completed the delivery review and shared action points.\n• Validated key changes and documented the findings.\n• Coordinated priorities with the team.',next_steps:'Finish the review checklist and prepare the daily handover.',blockers:'No blockers.',work_links:'https://example.com/tasks/review',support_person:'',submitted_at:at(270),updated_at:at(270),version:1,session_seconds_at_submit:15000}],leaves:[],holidays:[],exceptions:[],sessionEvents:[{id:'s1',session_id:'sample-session',employee_id:'sample-colleague',action:'pause',created_at:at(120),note:'Lunch Break'},{id:'s2',session_id:'sample-session',employee_id:'sample-colleague',action:'resume',created_at:at(140),note:''},{id:'s3',session_id:'sample-session',employee_id:'sample-colleague',action:'pause',created_at:at(350),note:'Personal break'},{id:'s4',session_id:'sample-session',employee_id:'sample-colleague',action:'resume',created_at:at(378),note:''}]};addSampleHistory(day);previewSample=true;previewEmployee='sample-colleague';if(!connected){me={...data.employees[0],role:me?.role||'employee'}}submissionDate=day;date=day;updateTab='eod';saveDraft(previewEmployee,day,'eod',{progress:'• Completed the sprint delivery review and shared next steps.\n• Validated release changes and documented the evidence.\n• Coordinated the next-day handover across the team.',work_links:'https://example.com/tasks/release-review\nhttps://example.com/docs/handover',next_steps:'Close the remaining review items and confirm tomorrow’s priorities.',blockers:'Awaiting final review on the release checklist.',support_person:'Reporting manager'});persist()}
function closingSummary(e,w){const endUpdate=data.updates.find(u=>u.employee_id===e.id&&u.work_date===w.work_date&&u.kind==='eod'),sec=sessionSeconds(w,now()),handover=endUpdate?.updated_at?Math.max(0,(now()-new Date(endUpdate.updated_at))/1000):null,needsReason=sec<28800||staleSession(w,now())||(handover!==null&&handover<1800);showDialog(`<div class="eyebrow">CLOSE THE LOOP</div><h2>Ready to sign out?</h2><p>Your closing message and time summary will be added to the daily thread.</p><div class="close-summary"><div><span>Net work</span><b>${hms(sec)}</b></div><div><span>Total breaks</span><b>${hms(breakSeconds(w,now()))}</b></div><div><span>Beyond 8 hours</span><b>${hms(Math.max(0,sec-28800))}</b></div></div><p class="sub">Signed in ${timeText(w.started_at,e.timezone)} · ${e.timezone}</p>${handover!==null&&handover<1800?'<div class="notice">The 30-minute feedback window after your latest EOD update is not complete. Stay available, or explain an early close below.</div>':''}${sec<28800?'<div class="notice">Your recorded work is below 8 hours. A reason will remain visible for HR review.</div>':''}<form id="closeWork"><label>${needsReason?'Reason for early / exceptional close':'Closing note'} ${needsReason?'*':'(optional)'}</label><textarea name="reason"  maxlength="2000" placeholder="Anything the team should know before you sign out?">${esc(needsReason?w.close_reason||'':'')}</textarea><div class="spacer"></div><button class="btn primary">Confirm sign-out ↗</button></form>`);associateLabels(modal);document.querySelector('#closeWork').onsubmit=ev=>{ev.preventDefault();action(()=>doWork('end',e,new FormData(ev.target).get('reason')))}}
let notifiedV4=new Set();setInterval(()=>{if(page!=='updates'||busy)return;const e=connected?me:data.employees.find(x=>x.id===previewEmployee);if(!e)return;const w=data.sessions.find(x=>x.employee_id===e.id&&x.work_date===submissionDate),sec=sessionSeconds(w,now()),br=breakSeconds(w,now()),elapsed=w?Math.max(0,(new Date(w.ended_at||now())-new Date(w.started_at))/1000):0;for(const [id,val] of [['workClock',hms(sec)],['breakClock',hms(br)],['elapsedClock',hms(elapsed)],['extraClock',hms(Math.max(0,sec-28800))],['wallClock',clockText(e.timezone)],['summaryWork',hms(sec)],['summaryBreak',hms(br)],['summaryExtra',hms(Math.max(0,sec-28800))]]){const el=document.getElementById(id);if(el)el.textContent=val}const bar=document.getElementById('workProgress');if(bar)bar.style.width=Math.min(100,sec/288)+'%';if(!w||w.ended_at||modal.open)return;for(const k of ['midday','eod'])if(status(e,w.work_date,k,data,now())==='Due'){const key=w.id+k;if(!notifiedV4.has(key)&&!sessionStorage.getItem('bevy-notice:'+key)){notifiedV4.add(key);sessionStorage.setItem('bevy-notice:'+key,'1');toast(k==='midday'?'A quick Mid-day update is due. Add a note if you cannot provide it.':'Prepare your EOD handover before finishing.');if('Notification'in window&&Notification.permission==='granted')new Notification('Bevy Daily Updates',{body:k==='midday'?'Mid-day checkpoint reached.':'Prepare your EOD handover, then remain available for feedback.'})}}},1000);

function renderLinks(text){return String(text).split(/\n/).filter(Boolean).map(line=>{const clean=line.trim();const url=safeUrl(clean);return url!=='#'?'<a href="'+esc(url)+'" target="_blank" rel="noopener noreferrer">'+esc(clean)+'</a>':esc(clean)}).join('<br>')}

function addSampleHistory(day){const last=dateAdd(day.slice(0,7)+'-01',-1),first=last.slice(0,7)+'-01';let i=0;for(let d=first;d<=last;d=dateAdd(d,1)){const dow=new Date(d+'T12:00:00Z').getUTCDay();if(dow===0||dow===6)continue;const start=new Date(d+'T04:00:00Z'),net=480+(i%5)*18,br=35+(i%4)*7,at=m=>new Date(start.getTime()+m*60000).toISOString(),id='sample-history-'+d;data.sessions.push({id,employee_id:'sample-colleague',work_date:d,started_at:start.toISOString(),ended_at:at(net+br),break_seconds:br*60,paused_at:null,needs_review:false});if(i%7===4)data.exceptions.push({id:'sample-ex-'+d,employee_id:'sample-colleague',work_date:d,category:'Work pressure',reason:'Sample: delivery volume prevented a separate Mid-day update.',status:i%2?'pending':'accepted',review_note:'Sample review context',submitted_at:at(260)});else data.updates.push({id:'sample-mid-'+d,employee_id:'sample-colleague',work_date:d,kind:'midday',progress:'• Reviewed priorities and completed planned work.\n• Shared the progress and supporting evidence.',next_steps:'Continue the remaining delivery tasks.',blockers:'No blockers.',work_links:'https://example.com/tasks/sample',submitted_at:at(260),updated_at:at(260),version:1,session_seconds_at_submit:14400});data.updates.push({id:'sample-end-'+d,employee_id:'sample-colleague',work_date:d,kind:'eod',progress:'• Completed the planned delivery and shared the handover.\n• Documented the outcome and next priorities.',next_steps:'Continue the agreed priorities next working day.',blockers:'No blockers.',work_links:'https://example.com/docs/sample',submitted_at:at(net+br-35),updated_at:at(net+br-35),version:1,session_seconds_at_submit:(net-35)*60});i++}reportAnchor=first}

function worldClocks(){return `<section class="world-clocks" aria-label="Team time zones">${[['Asia/Dhaka','Bangladesh','BST'],['America/New_York','Eastern Time',''],['Asia/Karachi','Pakistan','PKT']].map(([zone,label,abbr])=>{const c=zonedClock(now(),zone);return `<div class="world-clock"><span>${label} <b data-zone-label="${zone}">${abbr||c.abbreviation}</b></span><time data-zone-time="${zone}">${c.time}</time><small data-zone-date="${zone}">${c.date}</small></div>`}).join('')}</section>`}
setInterval(()=>{for(const el of document.querySelectorAll('[data-zone-time]')){const zone=el.dataset.zoneTime,c=zonedClock(now(),zone);el.textContent=c.time;document.querySelector(`[data-zone-date="${zone}"]`).textContent=c.date;if(zone==='America/New_York')document.querySelector(`[data-zone-label="${zone}"]`).textContent=c.abbreviation}},1000);
function breakForm(e){showDialog(`<div class="eyebrow">TAKE A MOMENT</div><h2>Start a break</h2><p>Working time pauses when you confirm. Resume when you return; break minutes are counted automatically.</p><form id="breakForm"><label for="breakType">Break type <span class="optional">Optional</span></label><select id="breakType" name="category"><option value="">General break</option>${['Lunch Break','Dinner Break','Prayer Break','Tea / Coffee Break','Personal Break','Other'].map(x=>`<option>${x}</option>`).join('')}</select><label for="breakNote">Note <span class="optional">Optional</span></label><input id="breakNote" name="note" maxlength="300" placeholder="Any context you would like to share"><div class="composer-actions"><button type="button" class="btn" id="cancelBreak">Cancel</button><button class="btn primary">Start break Ⅱ</button></div></form>`);document.querySelector('#cancelBreak').onclick=()=>modal.close();document.querySelector('#breakForm').onsubmit=ev=>{ev.preventDefault();const f=new FormData(ev.target),note=[f.get('category')||'General break',String(f.get('note')||'').trim()].filter(Boolean).join(' · ');action(()=>doWork('pause',e,note))}}
